/* The seller balance, changed in one place, once per event. Every change to a creator's balance (a sale, a refund, a dispute opened or won, a payout paid or returned, a hold released) was read, added to in the app and written back, so two changes at the same moment lost one of them, and Stripe sending payout.paid again counted the payout twice. public.ledger_post() now makes each change inside the database: it locks the creator's balance row, writes the event row under an idempotency key (ledger_events.idempotency_key, unique), and changes the balance by the same amounts, all or nothing, and a key already written changes nothing. public.ledger_release_due() releases every sale whose hold has ended the same way, creator by creator. Old events get their keys (the first sale row of an order, a payout's completion or return, a dispute's opening or closing), so events already recorded are not counted again. public.stripe_webhook_events records every Stripe event the webhook has finished, so a delivery Stripe repeats after it was handled is answered without doing anything twice. All three are the server's only. Until this runs the app changes balances as before. Run after `62`. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.ledger_events') IS NULL OR to_regclass('public.seller_ledger') IS NULL THEN RAISE NOTICE 'ledger skipped: public.ledger_events or public.seller_ledger does not exist here'; RETURN; END IF; ALTER TABLE public.ledger_events ADD COLUMN IF NOT EXISTS idempotency_key text; END $do$;
DO $do$ BEGIN IF to_regclass('public.ledger_events') IS NULL THEN RETURN; END IF; UPDATE public.ledger_events e SET idempotency_key = 'sale:' || e.order_id WHERE e.event_type = 'sale' AND e.order_id IS NOT NULL AND e.idempotency_key IS NULL AND NOT EXISTS (SELECT 1 FROM public.ledger_events x WHERE x.event_type = 'sale' AND x.order_id = e.order_id AND (x.created_at, x.id) < (e.created_at, e.id)) AND NOT EXISTS (SELECT 1 FROM public.ledger_events y WHERE y.idempotency_key = 'sale:' || e.order_id); UPDATE public.ledger_events e SET idempotency_key = 'payout:' || e.stripe_payout_id || ':' || e.event_type WHERE e.event_type IN ('cashout_completed', 'cashout_failed') AND e.stripe_payout_id IS NOT NULL AND e.idempotency_key IS NULL AND NOT EXISTS (SELECT 1 FROM public.ledger_events x WHERE x.event_type = e.event_type AND x.stripe_payout_id = e.stripe_payout_id AND (x.created_at, x.id) < (e.created_at, e.id)) AND NOT EXISTS (SELECT 1 FROM public.ledger_events y WHERE y.idempotency_key = 'payout:' || e.stripe_payout_id || ':' || e.event_type); UPDATE public.ledger_events e SET idempotency_key = 'dispute:' || e.stripe_dispute_id || ':' || e.event_type WHERE e.event_type IN ('dispute_created', 'dispute_closed') AND e.stripe_dispute_id IS NOT NULL AND e.idempotency_key IS NULL AND NOT EXISTS (SELECT 1 FROM public.ledger_events x WHERE x.event_type = e.event_type AND x.stripe_dispute_id = e.stripe_dispute_id AND (x.created_at, x.id) < (e.created_at, e.id)) AND NOT EXISTS (SELECT 1 FROM public.ledger_events y WHERE y.idempotency_key = 'dispute:' || e.stripe_dispute_id || ':' || e.event_type); END $do$;
DO $do$ BEGIN IF to_regclass('public.ledger_events') IS NULL THEN RETURN; END IF; CREATE UNIQUE INDEX IF NOT EXISTS ledger_events_once ON public.ledger_events (idempotency_key) WHERE idempotency_key IS NOT NULL; END $do$;
CREATE TABLE IF NOT EXISTS public.stripe_webhook_events (event_id text PRIMARY KEY, type text NOT NULL, account text, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, attempts integer NOT NULL DEFAULT 1, last_error text);
CREATE INDEX IF NOT EXISTS stripe_webhook_events_unfinished_idx ON public.stripe_webhook_events (received_at) WHERE processed_at IS NULL;
ALTER TABLE public.stripe_webhook_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.stripe_webhook_events FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.ledger_post(p_creator uuid, p_key text, p_op text, p_amount bigint, p_event jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE l public.seller_ledger%ROWTYPE; d_p bigint := 0; d_a bigint := 0; d_t bigint := 0; d_n bigint := 0; rem bigint; take bigint; ev uuid; BEGIN IF p_creator IS NULL OR p_amount IS NULL OR p_amount < 0 THEN RAISE EXCEPTION 'ledger_post: a creator and an amount of zero or more are needed'; END IF; INSERT INTO public.seller_ledger (creator_id) VALUES (p_creator) ON CONFLICT (creator_id) DO NOTHING; SELECT * INTO l FROM public.seller_ledger WHERE creator_id = p_creator FOR UPDATE; IF p_key IS NOT NULL AND EXISTS (SELECT 1 FROM public.ledger_events WHERE idempotency_key = p_key) THEN RETURN jsonb_build_object('applied', false); END IF; IF p_op = 'sale' THEN take := least(p_amount, l.negative_balance); d_n := -take; d_p := p_amount - take; ELSIF p_op = 'credit_available' THEN take := least(p_amount, l.negative_balance); d_n := -take; d_a := p_amount - take; ELSIF p_op IN ('debit_pending_first', 'debit_available_first') THEN rem := p_amount; IF p_op = 'debit_pending_first' THEN take := least(rem, l.pending_amount); d_p := -take; rem := rem - take; take := least(rem, l.available_amount); d_a := -take; rem := rem - take; ELSE take := least(rem, l.available_amount); d_a := -take; rem := rem - take; take := least(rem, l.pending_amount); d_p := -take; rem := rem - take; END IF; d_n := rem; ELSIF p_op = 'payout_paid' THEN d_t := -least(p_amount, l.in_transit_amount); ELSIF p_op = 'payout_returned' THEN d_t := -least(p_amount, l.in_transit_amount); d_a := p_amount; ELSIF p_op = 'record' THEN NULL; ELSE RAISE EXCEPTION 'ledger_post: unknown change %', p_op; END IF; INSERT INTO public.ledger_events (creator_id, event_type, amount_cents, net_seller_cents, fee_cents, currency, pending_delta, available_delta, in_transit_delta, order_id, stripe_payout_id, stripe_refund_id, stripe_dispute_id, hold_until, description, metadata, idempotency_key) VALUES (p_creator, p_event ->> 'event_type', coalesce((p_event ->> 'amount_cents')::integer, p_amount::integer), coalesce((p_event ->> 'net_seller_cents')::integer, p_amount::integer), coalesce((p_event ->> 'fee_cents')::integer, 0), coalesce(p_event ->> 'currency', 'usd'), d_p, d_a, d_t, (p_event ->> 'order_id')::uuid, p_event ->> 'stripe_payout_id', p_event ->> 'stripe_refund_id', p_event ->> 'stripe_dispute_id', (p_event ->> 'hold_until')::timestamptz, p_event ->> 'description', coalesce(p_event -> 'metadata', '{}'::jsonb), p_key) ON CONFLICT DO NOTHING RETURNING id INTO ev; IF ev IS NULL THEN RETURN jsonb_build_object('applied', false); END IF; UPDATE public.seller_ledger SET pending_amount = pending_amount + d_p, available_amount = available_amount + d_a, in_transit_amount = in_transit_amount + d_t, negative_balance = negative_balance + d_n, lifetime_earnings = lifetime_earnings + coalesce((p_event ->> 'add_lifetime_earnings')::integer, 0), lifetime_fees = lifetime_fees + coalesce((p_event ->> 'add_lifetime_fees')::integer, 0), lifetime_refunds = lifetime_refunds + coalesce((p_event ->> 'add_lifetime_refunds')::integer, 0), lifetime_paid_out = lifetime_paid_out + CASE WHEN p_op = 'payout_paid' THEN p_amount::integer ELSE 0 END WHERE creator_id = p_creator; RETURN jsonb_build_object('applied', true, 'event_id', ev, 'pending_delta', d_p, 'available_delta', d_a, 'in_transit_delta', d_t, 'negative_delta', d_n); END $f$;
CREATE OR REPLACE FUNCTION public.ledger_release_due(p_now timestamptz DEFAULT now()) RETURNS TABLE (creator_id uuid, released bigint, to_available bigint, events integer) LANGUAGE plpgsql SET search_path = public AS $f$ #variable_conflict use_column DECLARE c uuid; ids uuid[]; amt bigint; take bigint; l public.seller_ledger%ROWTYPE; BEGIN FOR c IN SELECT DISTINCT e.creator_id FROM public.ledger_events e WHERE e.event_type = 'sale' AND e.released_at IS NULL AND e.hold_until <= p_now LOOP INSERT INTO public.seller_ledger (creator_id) VALUES (c) ON CONFLICT (creator_id) DO NOTHING; SELECT * INTO l FROM public.seller_ledger s WHERE s.creator_id = c FOR UPDATE; SELECT array_agg(x.id ORDER BY x.id) INTO ids FROM (SELECT e.id FROM public.ledger_events e WHERE e.creator_id = c AND e.event_type = 'sale' AND e.released_at IS NULL AND e.hold_until <= p_now FOR UPDATE SKIP LOCKED) x; IF ids IS NULL THEN CONTINUE; END IF; SELECT coalesce(sum(greatest(0, coalesce(s.net_seller_cents, 0) - coalesce((SELECT sum(greatest(0, -coalesce(r.pending_delta, 0))) FROM public.ledger_events r WHERE r.event_type = 'refund' AND r.order_id = s.order_id), 0))), 0) INTO amt FROM public.ledger_events s WHERE s.id = ANY (ids); UPDATE public.ledger_events e SET released_at = p_now WHERE e.id = ANY (ids); take := least(amt, l.negative_balance); UPDATE public.seller_ledger s SET pending_amount = greatest(0, s.pending_amount - amt), available_amount = s.available_amount + (amt - take), negative_balance = s.negative_balance - take WHERE s.creator_id = c; INSERT INTO public.ledger_events (creator_id, event_type, amount_cents, net_seller_cents, currency, pending_delta, available_delta, description, idempotency_key) VALUES (c, 'hold_release', amt::integer, (amt - take)::integer, 'usd', (-least(amt, l.pending_amount))::integer, (amt - take)::integer, 'Hold released: $' || to_char(amt / 100.0, 'FM999999990.00') || ' cleared', 'release:' || c || ':' || md5(array_to_string(ids, ','))); creator_id := c; released := amt; to_available := amt - take; events := array_length(ids, 1); RETURN NEXT; END LOOP; END $f$;
REVOKE ALL ON FUNCTION public.ledger_post(uuid, text, text, bigint, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ledger_post(uuid, text, text, bigint, jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.ledger_release_due(timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ledger_release_due(timestamptz) TO service_role;
notify pgrst, 'reload schema';
